"""Exact max-flow and min-cost circulation primitives for the controller."""
from collections import deque


class Dinic:
    __slots__ = ('n', 'adj', 'to', 'cap')

    def __init__(self, n):
        self.n = n
        self.adj = [[] for _ in range(n)]
        self.to = []
        self.cap = []

    def add(self, u, v, c):
        if c <= 0:
            return -1
        idx = len(self.to)
        self.to.append(v)
        self.cap.append(c)
        self.adj[u].append(idx)
        self.to.append(u)
        self.cap.append(0)
        self.adj[v].append(idx + 1)
        return idx

    def maxflow(self, s, t, limit):
        n = self.n
        adj = self.adj
        to = self.to
        cap = self.cap
        flow = 0
        while flow < limit:
            level = [-1] * n
            level[s] = 0
            dq = deque([s])
            while dq:
                u = dq.popleft()
                for eid in adj[u]:
                    if cap[eid] > 0:
                        v = to[eid]
                        if level[v] < 0:
                            level[v] = level[u] + 1
                            dq.append(v)
            if level[t] < 0:
                break
            it = [0] * n

            def dfs(u, f):
                if u == t:
                    return f
                au = adj[u]
                i = it[u]
                while i < len(au):
                    eid = au[i]
                    v = to[eid]
                    if cap[eid] > 0 and level[v] == level[u] + 1:
                        ret = dfs(v, f if f < cap[eid] else cap[eid])
                        if ret:
                            cap[eid] -= ret
                            cap[eid ^ 1] += ret
                            it[u] = i
                            return ret
                    i += 1
                    it[u] = i
                return 0

            while flow < limit:
                f = dfs(s, limit - flow)
                if not f:
                    break
                flow += f
        return flow

    def reachable(self, s):
        seen = [False] * self.n
        seen[s] = True
        dq = deque([s])
        while dq:
            u = dq.popleft()
            for eid in self.adj[u]:
                if self.cap[eid] > 0:
                    v = self.to[eid]
                    if not seen[v]:
                        seen[v] = True
                        dq.append(v)
        return seen


class NetworkSimplex:
    """Minimum-cost circulation with lower/upper bounds.

    The caller supplies a feasible integral circulation.  A feasible basic
    spanning-tree solution is constructed by removing cycles in the interior
    support, then bounded network simplex is run to optimality.
    """

    def __init__(self, n, arc_tuples, initial_flow):
        self.n = n
        self.fr = []
        self.to = []
        self.lo = []
        self.hi = []
        self.cost = []
        self.flow = []
        self.basic = []
        for (u, v, l, h, c), f in zip(arc_tuples, initial_flow):
            if not (0 <= u < n and 0 <= v < n and 0 <= l <= f <= h):
                raise ValueError('bad circulation arc')
            eid = len(self.fr)
            self.fr.append(u)
            self.to.append(v)
            self.lo.append(l)
            self.hi.append(h)
            self.cost.append(c)
            self.flow.append(f)
            self.basic.append(0)
        self.E = len(self.fr)
        self.tadj = [[] for _ in range(n)]
        self.iters = 0
        self.bound_flips = 0
        self.degenerate = 0
        self._make_basis()
        self.max_iters = 2000000

    def _make_basis(self):
        n = self.n
        fr = self.fr
        to = self.to
        lo = self.lo
        hi = self.hi
        flow = self.flow
        inside = [lo[i] < flow[i] < hi[i] for i in range(self.E)]

        # Repeatedly adjust a cycle of interior arcs until their support is a
        # forest.  This is also a useful preconditioning step for simplex.
        rounds = 0
        while True:
            parent = list(range(n))
            rank = [0] * n

            def find(x):
                while parent[x] != x:
                    parent[x] = parent[parent[x]]
                    x = parent[x]
                return x

            def union(a, b):
                ra = find(a)
                rb = find(b)
                if ra == rb:
                    return False
                if rank[ra] < rank[rb]:
                    ra, rb = rb, ra
                parent[rb] = ra
                if rank[ra] == rank[rb]:
                    rank[ra] += 1
                return True

            fadj = [[] for _ in range(n)]
            cycle_eid = -1
            for i in range(self.E):
                if inside[i]:
                    u = fr[i]
                    v = to[i]
                    if union(u, v):
                        fadj[u].append(i)
                        fadj[v].append(i)
                    elif cycle_eid < 0:
                        cycle_eid = i
            if cycle_eid < 0:
                break

            u = fr[cycle_eid]
            v = to[cycle_eid]
            par = [-2] * n
            pare = [-1] * n
            par[u] = -1
            dq = deque([u])
            while dq:
                x = dq.popleft()
                if x == v:
                    break
                for ee in fadj[x]:
                    a = fr[ee]
                    b = to[ee]
                    y = b if a == x else a
                    if par[y] == -2:
                        par[y] = x
                        pare[y] = ee
                        dq.append(y)
            if par[v] == -2:
                raise RuntimeError('interior forest path')
            path = []
            cur = v
            while cur != u:
                path.append(pare[cur])
                cur = par[cur]
            path.reverse()

            # Traversal: u -> forest path -> v -> closing edge back to u.
            cur = u
            theta = None
            dirs = []
            for ee in path:
                a = fr[ee]
                b = to[ee]
                forward = (a == cur)
                nxt = b if forward else a
                res = (hi[ee] - flow[ee]) if forward else (flow[ee] - lo[ee])
                if res <= 0:
                    raise RuntimeError('interior residual')
                dirs.append(forward)
                if theta is None or res < theta:
                    theta = res
                cur = nxt
            if cur != v:
                raise RuntimeError('interior path end')
            a = fr[cycle_eid]
            b = to[cycle_eid]
            forward = (a == cur)
            res = (hi[cycle_eid] - flow[cycle_eid]) if forward else (flow[cycle_eid] - lo[cycle_eid])
            if res <= 0:
                raise RuntimeError('interior closing residual')
            if theta is None or res < theta:
                theta = res
            if theta is None or theta <= 0:
                raise RuntimeError('interior cycle adjustment')

            cur = u
            for ee, fwd in zip(path, dirs):
                if fwd:
                    flow[ee] += theta
                else:
                    flow[ee] -= theta
                a = fr[ee]
                b = to[ee]
                cur = b if a == cur else a
            flow[cycle_eid] += theta if forward else -theta
            for i in range(self.E):
                if inside[i] and not (lo[i] < flow[i] < hi[i]):
                    inside[i] = False
            rounds += 1
            if rounds > self.E + 5:
                raise RuntimeError('interior cycle rounds')

        # Extend the interior forest to a spanning tree, preferring interior
        # arcs so every non-tree arc ends up at one of its bounds.
        parent = list(range(n))
        rank = [0] * n

        def find2(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union2(a, b):
            ra = find2(a)
            rb = find2(b)
            if ra == rb:
                return False
            if rank[ra] < rank[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            if rank[ra] == rank[rb]:
                rank[ra] += 1
            return True

        tree = []
        for i in range(self.E):
            if lo[i] < flow[i] < hi[i]:
                if not union2(fr[i], to[i]):
                    raise RuntimeError('interior cycle remains')
                tree.append(i)
        for i in range(self.E):
            if not (lo[i] < flow[i] < hi[i]):
                if union2(fr[i], to[i]):
                    tree.append(i)
        if len(tree) != n - 1:
            raise RuntimeError('circulation graph disconnected')
        for eid in tree:
            self.basic[eid] = 1
            self.tadj[fr[eid]].append(eid)
            self.tadj[to[eid]].append(eid)

    def potentials(self):
        n = self.n
        pi = [None] * n
        pi[0] = 0
        dq = deque([0])
        while dq:
            u = dq.popleft()
            pu = pi[u]
            for eid in self.tadj[u]:
                a = self.fr[eid]
                b = self.to[eid]
                if a == u:
                    if pi[b] is None:
                        pi[b] = pu + self.cost[eid]
                        dq.append(b)
                elif b == u:
                    if pi[a] is None:
                        pi[a] = pu - self.cost[eid]
                        dq.append(a)
                else:
                    raise RuntimeError('bad basis tree')
        if any(x is None for x in pi):
            raise RuntimeError('disconnected basis tree')
        return pi

    def _tree_path(self, start, target):
        n = self.n
        par = [-2] * n
        pare = [-1] * n
        par[start] = -1
        dq = deque([start])
        while dq:
            u = dq.popleft()
            if u == target:
                break
            for eid in self.tadj[u]:
                a = self.fr[eid]
                b = self.to[eid]
                v = b if a == u else a
                if par[v] == -2:
                    par[v] = u
                    pare[v] = eid
                    dq.append(v)
        if par[target] == -2:
            raise RuntimeError('basis tree path')
        path = []
        cur = target
        while cur != start:
            path.append(pare[cur])
            cur = par[cur]
        path.reverse()
        return path

    def solve(self, verbose=False, rule='dantzig', special=None):
        n = self.n
        E = self.E
        assigned = None
        if special is not None:
            # assigned[j] is the slot of the selected incoming eligibility arc.
            assigned = [-1] * len(special['win_ranges'])
            for eid, ss, jj in special['elig']:
                if self.flow[eid] > 0:
                    assigned[jj] = ss

        INF = 10 ** 80
        MASK = (1 << 64) - 1

        def mix(x):
            x = (x + 0x9E3779B97F4A7C15) & MASK
            x = ((x ^ (x >> 30)) * 0xBF58476D1CE4E5B9) & MASK
            x = ((x ^ (x >> 27)) * 0x94D049BB133111EB) & MASK
            return (x ^ (x >> 31)) & MASK

        rand1 = [mix(i + 1) for i in range(E)]
        rand2 = [mix(i + 0x123456789ABCDEF) for i in range(E)]

        def contrib(eid):
            if self.basic[eid]:
                return rand1[eid]
            if self.lo[eid] < self.hi[eid] and self.flow[eid] == self.hi[eid]:
                return rand2[eid]
            return 0

        state_hash = 0
        for ei in range(E):
            state_hash ^= contrib(ei)
        seen_states = {state_hash}
        force_bland = False

        while True:
            self.iters += 1
            if self.iters > self.max_iters:
                raise RuntimeError('simplex iteration limit')
            pi = self.potentials()
            enter = -1
            alpha = 0
            bestscore = None
            use_bland = force_bland or rule == 'bland'

            if use_bland:
                # Bland's smallest-index entering rule gives a finite pivot
                # sequence after a repeated basis/state is detected.
                for eid in range(E):
                    if self.basic[eid]:
                        continue
                    l = self.lo[eid]
                    h = self.hi[eid]
                    if h <= l:
                        continue
                    x = self.flow[eid]
                    rc = self.cost[eid] + pi[self.fr[eid]] - pi[self.to[eid]]
                    if x == l:
                        if rc < 0:
                            enter = eid
                            alpha = 1
                            break
                    elif x == h:
                        if rc > 0:
                            enter = eid
                            alpha = -1
                            break
                    else:
                        raise RuntimeError('nonbasic interior arc')
            elif special is None:
                # Dantzig's rule on the full residual network.
                for eid in range(E):
                    if self.basic[eid]:
                        continue
                    l = self.lo[eid]
                    h = self.hi[eid]
                    if h <= l:
                        continue
                    x = self.flow[eid]
                    rc = self.cost[eid] + pi[self.fr[eid]] - pi[self.to[eid]]
                    if x == l:
                        if rc < 0:
                            score = -rc
                            if bestscore is None or score > bestscore:
                                bestscore = score
                                enter = eid
                                alpha = 1
                    elif x == h:
                        if rc > 0:
                            score = rc
                            if bestscore is None or score > bestscore:
                                bestscore = score
                                enter = eid
                                alpha = -1
                    else:
                        raise RuntimeError('nonbasic interior arc')
            else:
                # Fast Dantzig search.  Zero-cost arcs are scanned directly;
                # all eligibility arcs are handled by a range minimum because
                # their cost separates into slot and window terms.
                for eid in special['zero_eids']:
                    if self.basic[eid]:
                        continue
                    l = self.lo[eid]
                    h = self.hi[eid]
                    if h <= l:
                        continue
                    x = self.flow[eid]
                    rc = self.cost[eid] + pi[self.fr[eid]] - pi[self.to[eid]]
                    if x == l:
                        if rc < 0:
                            score = -rc
                            if (bestscore is None or score > bestscore or
                                    (score == bestscore and eid < enter)):
                                bestscore = score
                                enter = eid
                                alpha = 1
                    elif x == h:
                        if rc > 0:
                            score = rc
                            if (bestscore is None or score > bestscore or
                                    (score == bestscore and eid < enter)):
                                bestscore = score
                                enter = eid
                                alpha = -1
                    else:
                        raise RuntimeError('nonbasic interior arc')

                S = special['S']
                mat = special['elig_matrix']
                wr = special['win_ranges']
                wnodes = special['wnodes']
                base = special['win_base']
                times = special['slot_times']
                enodes = special['enodes']
                if S:
                    size = 1
                    while size < S:
                        size *= 2
                    segv = [INF] * (2 * size)
                    segp = [-1] * (2 * size)
                    for ss in range(S):
                        segv[size + ss] = times[ss] + pi[enodes[ss]]
                        segp[size + ss] = ss
                    for k in range(size - 1, 0, -1):
                        a = segv[2 * k]
                        b = segv[2 * k + 1]
                        if a <= b:
                            segv[k] = a
                            segp[k] = segp[2 * k]
                        else:
                            segv[k] = b
                            segp[k] = segp[2 * k + 1]

                    def query(lo, hi):
                        lo += size
                        hi += size + 1
                        v = INF
                        p = -1
                        while lo < hi:
                            if lo & 1:
                                if segv[lo] < v or (segv[lo] == v and (p < 0 or segp[lo] < p)):
                                    v = segv[lo]
                                    p = segp[lo]
                                lo += 1
                            if hi & 1:
                                hi -= 1
                                if segv[hi] < v or (segv[hi] == v and (p < 0 or segp[hi] < p)):
                                    v = segv[hi]
                                    p = segp[hi]
                            lo //= 2
                            hi //= 2
                        if v >= INF // 2:
                            return INF, -1
                        return v, p

                    def update(pos, val):
                        k = size + pos
                        segv[k] = val
                        segp[k] = pos if val < INF // 2 else -1
                        k //= 2
                        while k:
                            a = segv[2 * k]
                            b = segv[2 * k + 1]
                            if a <= b:
                                segv[k] = a
                                segp[k] = segp[2 * k]
                            else:
                                segv[k] = b
                                segp[k] = segp[2 * k + 1]
                            k //= 2

                    for jj, (lo, hi) in enumerate(wr):
                        if lo < 0:
                            continue
                        wc = base[jj] - pi[wnodes[jj]]
                        masked = []
                        while True:
                            av, ss = query(lo, hi)
                            if ss < 0 or av >= INF // 2:
                                break
                            eid = mat[jj][ss]
                            if eid < 0:
                                break
                            if self.basic[eid] or self.flow[eid] != self.lo[eid]:
                                masked.append((ss, times[ss] + pi[enodes[ss]]))
                                update(ss, INF)
                                continue
                            rc = av + wc
                            if rc < 0:
                                score = -rc
                                if (bestscore is None or score > bestscore or
                                        (score == bestscore and eid < enter)):
                                    bestscore = score
                                    enter = eid
                                    alpha = 1
                            break
                        for ss, val in masked:
                            update(ss, val)

                # The only eligibility arcs at their upper bound are selected
                # assignments.  Tracking those avoids a second large scan.
                for jj, ss in enumerate(assigned):
                    if ss < 0:
                        continue
                    eid = mat[jj][ss]
                    if self.basic[eid]:
                        continue
                    rc = self.cost[eid] + pi[self.fr[eid]] - pi[self.to[eid]]
                    if rc > 0:
                        score = rc
                        if (bestscore is None or score > bestscore or
                                (score == bestscore and eid < enter)):
                            bestscore = score
                            enter = eid
                            alpha = -1

            if enter < 0:
                self.assigned = assigned
                return True

            u = self.fr[enter]
            v = self.to[enter]
            start, end = (v, u) if alpha == 1 else (u, v)
            path = self._tree_path(start, end)
            enter_res = (self.hi[enter] - self.flow[enter]) if alpha == 1 else (self.flow[enter] - self.lo[enter])
            theta = enter_res
            leave = -1
            cur = start
            dirs = []
            for eid in path:
                a = self.fr[eid]
                b = self.to[eid]
                if a == cur:
                    forward = True
                    nxt = b
                elif b == cur:
                    forward = False
                    nxt = a
                else:
                    raise RuntimeError('cycle path direction')
                res = (self.hi[eid] - self.flow[eid]) if forward else (self.flow[eid] - self.lo[eid])
                dirs.append(forward)
                if res < theta:
                    theta = res
                    leave = eid
                elif res == theta:
                    if leave < 0 or eid < leave:
                        leave = eid
                cur = nxt
            if cur != end:
                raise RuntimeError('cycle path end')
            if theta < 0:
                raise RuntimeError('negative pivot amount')

            touched = {}
            if theta:
                cur = start
                for eid, fwd in zip(path, dirs):
                    oldf = self.flow[eid]
                    if fwd:
                        self.flow[eid] += theta
                    else:
                        self.flow[eid] -= theta
                    if (special is not None and special['elig_slot'][eid] >= 0 and
                            self.flow[eid] != oldf):
                        jj = special['elig_win'][eid]
                        touched.setdefault(jj, []).append((eid, special['elig_slot'][eid]))
                    cur = self.to[eid] if self.fr[eid] == cur else self.fr[eid]
                oldf = self.flow[enter]
                self.flow[enter] += alpha * theta
                if (special is not None and special['elig_slot'][enter] >= 0 and
                        self.flow[enter] != oldf):
                    jj = special['elig_win'][enter]
                    touched.setdefault(jj, []).append((enter, special['elig_slot'][enter]))
                if special is not None:
                    # Resolve after the whole cycle has been applied: a pivot
                    # may both release an old slot and take a new one.
                    for jj, chg in touched.items():
                        nv = -1
                        for ee, ss2 in chg:
                            if self.flow[ee] > 0:
                                nv = ss2
                                break
                        assigned[jj] = nv
            else:
                self.degenerate += 1

            state_hash ^= contrib(enter)
            if leave >= 0:
                state_hash ^= contrib(leave)
                self.basic[leave] = 0
                a = self.fr[leave]
                b = self.to[leave]
                try:
                    self.tadj[a].remove(leave)
                except ValueError:
                    pass
                try:
                    self.tadj[b].remove(leave)
                except ValueError:
                    pass
                self.basic[enter] = 1
                self.tadj[u].append(enter)
                self.tadj[v].append(enter)
            else:
                self.bound_flips += 1
            state_hash ^= contrib(enter)
            if leave >= 0:
                state_hash ^= contrib(leave)
            if state_hash in seen_states:
                force_bland = True
            else:
                seen_states.add(state_hash)

            if verbose and self.iters % 1000 == 0:
                import sys
                print('iter', self.iters, 'enter', enter, 'theta', theta,
                      'leave', leave, 'degen', self.degenerate, file=sys.stderr)

    def objective(self):
        return sum(self.cost[i] * self.flow[i] for i in range(self.E))
